#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using Newtonsoft.Json;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
// Runs existing suites unchanged, each in a fresh Play session. No product runtime hooks.
[InitializeOnLoad] public static class ConfidenceRegressionRunner
{
 const string Key="ConfidenceRegression.";static double readyAt;static int frame=-1;
 static string Root=>SessionState.GetString(Key+"root","");static int Phase{get=>SessionState.GetInt(Key+"phase",0);set=>SessionState.SetInt(Key+"phase",value);}static string State{get=>SessionState.GetString(Key+"state","");set=>SessionState.SetString(Key+"state",value);}
 static ConfidenceRegressionRunner(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=Mode;EditorApplication.delayCall+=TryRequest;}
 static void TryRequest(){string after=Path.Combine(Application.dataPath,"../Logs/ConfidenceLabelsAfter.request");if(File.Exists(after)&&!SessionState.GetBool(Key+"active",false)){File.Delete(after);StartAfter();return;}string request=Path.Combine(Application.dataPath,"../Logs/ConfidenceLabelsBaseline.request");if(File.Exists(request)&&!SessionState.GetBool(Key+"active",false)){File.Delete(request);StartBaseline();}}
 public static void StartBaseline(){Start("Baseline");}public static void StartAfter(){Start("After");}
 static void Start(string name){if(SessionState.GetBool(Key+"active",false))return;var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-confidenceOutput");string root=i>=0?args[i+1]:@"C:\Users\chlgu\Documents\Codex\2026-10-19\unity-mcp-main-scene-hierarchy-towercraneroot\outputs\ConfidenceLabels";SessionState.SetString(Key+"root",Path.Combine(root,name));Directory.CreateDirectory(Root);Phase=0;State="edit";SessionState.SetBool(Key+"active",true);readyAt=EditorApplication.timeSinceStartup+2;Write("STARTED");}
 static void Write(string s){File.WriteAllText(Path.Combine(Root,"RunnerStatus.json"),JsonConvert.SerializeObject(new{status=s,phase=Phase,state=State,playing=EditorApplication.isPlaying,utc=DateTime.UtcNow},Formatting.Indented));}
 static void Mode(PlayModeStateChange mode){if(!SessionState.GetBool(Key+"active",false))return;if(mode==PlayModeStateChange.EnteredPlayMode){State="ready";readyAt=EditorApplication.timeSinceStartup+3;}if(mode==PlayModeStateChange.EnteredEditMode&&State=="leave"){Phase++;State="enter";readyAt=EditorApplication.timeSinceStartup+2;} }
 static string Folder=>Path.Combine(Root,new[]{"Edit","Regression","Explore","WorkerRoute","AccidentEvidence","DB"}[Mathf.Min(Phase,5)]);
 static bool Running=>Phase==1?ShipyardPlayChecks.Running:Phase==2?ShipyardExploreChecks.Running:Phase==3?WorkerRouteRiskChecks.Running:Phase==4?AccidentEvidenceChecks.Running:Phase==5?ShipyardPublicDataChecks.Running:false;
 static void Tick(){if(SessionState.GetBool(Key+"active",false)&&Application.isPlaying){EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView")).Repaint();EditorApplication.QueuePlayerLoopUpdate();}if(!SessionState.GetBool(Key+"active",false)||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.timeSinceStartup<readyAt)return;try{
 if(State=="edit"){if(EditorApplication.isPlaying){EditorApplication.isPlaying=false;return;}if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().path!="Assets/Scenes/Main.unity")EditorSceneManager.OpenScene("Assets/Scenes/Main.unity");if(Path.GetFileName(Root)=="After"){ShipyardConfidenceLabelUpgrade.Apply(Root);ShipyardConfidenceChecks.Run(Path.Combine(Root,"Targeted"));}ShipyardPublicDataChecks.Structure(Path.Combine(Root,"Edit"));AccidentEvidenceChecks.Core(Path.Combine(Root,"AccidentEvidence"));CaptureRig();Phase=1;State="enter";Write("EDIT_PASSED");}
 else if(State=="enter"){if(Phase>5){Finish();return;}Write("ENTERING");State="changing";EditorApplication.isPlaying=true;}
 else if(State=="ready"){var game=EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView"));game.Show();game.Focus();Application.runInBackground=true;Application.targetFrameRate=60;Directory.CreateDirectory(Folder);if(Phase==1)ShipyardPlayChecks.Run(Folder);if(Phase==2)ShipyardExploreChecks.Run(Folder);if(Phase==3)WorkerRouteRiskChecks.Run(Folder);if(Phase==4)AccidentEvidenceChecks.Play(Folder);if(Phase==5)ShipyardPublicDataChecks.Play(Folder);State="running";frame=Time.frameCount;Write("RUNNING");}
 else if(State=="running"&&!Running&&Time.frameCount>frame+2){Write("SUITE_FINISHED");State="leave";EditorApplication.isPlaying=false;}
 }catch(Exception ex){File.AppendAllText(Path.Combine(Root,"RunnerErrors.txt"),ex+"\n");SessionState.SetBool(Key+"active",false);Write("FAILED");}}
 static void CaptureRig(){var t=GameObject.Find("TowerCraneRoot").transform;File.WriteAllText(Path.Combine(Root,"Rig.json"),JsonConvert.SerializeObject(new{worldPosition=new[]{t.position.x,t.position.y,t.position.z},worldRotation=new[]{t.rotation.x,t.rotation.y,t.rotation.z,t.rotation.w},localScale=new[]{t.localScale.x,t.localScale.y,t.localScale.z},parent=t.parent? t.parent.name:null},Formatting.Indented));}
 static void Finish(){SessionState.SetBool(Key+"active",false);State="complete";CaptureRig();Write("COMPLETE");}
}
#endif
